        if ((context?.kind === 'archive' || context?.kind === 'workflow') && !/^(?:[a-z]+:|\/)/iu.test(href)) api(context.kind + '.asset', { documentPath: context.id, href, knowledgeBaseId: context.knowledgeBaseId }).then((value) => { if (active) setSrc(value.src) }, () => {})
